package net.flashlight.battery;
import java.util.*;import net.minecraft.client.Minecraft;import mod.cdv.tnpc.entity.AutoGunOperator;
public class NpcChecks15 {static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}public static class World extends EntityChecks14.World {public List<Object> npcs=new ArrayList<>();public Iterable<Object> entitiesForRendering(){return npcs;}}
 public static void main(String[]args){World w=new World();var p=new ShadowChecks6.Actor();p.world=w;Minecraft.INSTANCE.level=w;Minecraft.INSTANCE.player=p;AutoGunOperator npc=new AutoGunOperator();npc.world=w;npc.off=ShadowChecks6.s("flashlight:flashlight");w.npcs.add(npc);Light6.tick();ok(Light6.cache.containsKey(npc),"NPC light enters actual world renderer without player inventory");ok(Light6.cache.get(npc).range==25,"NPC gets full realistic cone range");ok(Light6.cache.get(npc).origin[1]<1.3,"beam starts at carried hand height");var body=new EntityChecks14.Actor();body.z=3;ok((EntityLight14.light(body,0,0)&240)>0,"NPC light illuminates native entity textures");for(int i=0;i<20;i++){var other=new AutoGunOperator();other.world=w;other.off=ShadowChecks6.s("flashlight:flashlight");w.npcs.add(other);}p.main=ShadowChecks6.s("flashlight:flashlight");Light6.tick();ok(Light6.cache.size()<=2&&Light6.cache.containsKey(p),"player priority and bounded source count");ok(Light6.lastRays<=48,"shared ray budget independent of NPC count");npc.off=ShadowChecks6.s("flashlight:flashlight_off");ok(!Light6.source(npc),"unlit NPC source never accesses player inventory");npc.off=ShadowChecks6.s("flashlight:flashlight");npc.alive=false;ok(!Light6.source(npc),"dead NPC cannot emit stale light");w.npcs.clear();p.main=ShadowChecks6.s("minecraft:air");Light6.tick();ok(Light6.cache.isEmpty(),"removal and off clear cone cache");System.out.println("NPC_REAL_CONE_NATIVE_TEXTURE_LIFECYCLE_AND_BUDGET_CHECKS="+n);}
}